from itertools import combinations

def max_students_to_lunch(n, groups, k, x, a, b):
    def can_take(lunches_needed, max_campers):
        return a <= lunches_needed <= max_campers

    def count_lunches(groups):
        return sum(group for group in groups)

    def backtrack(start, current_groups, current_lunches, current_campers):
        if current_lunches > k * x:
            return False
        if can_take(current_lunches, current_campers):
            return True

        for i in range(start, n):
            if count_lunches(current_groups + [groups[i]]) <= k * x:
                if backtrack(i + 1, current_groups + [groups[i]], current_lunches + groups[i], current_campers + groups[i]):
                    return True
        return False

    max_students = 0
    for r in range(1, n + 1):
        for combo in combinations(groups, r):
            if count_lunches(combo) <= k * x and can_take(count_lunches(combo), sum(combo)):
                max_students = max(max_students, sum(combo))

    return max_students if max_students >= a else 'impossible'

